import ast

# Parse the code
user_code = code
tree = ast.parse(user_code)

# Check for correct import
found_datetime = False
found_timedelta = False

for node in ast.walk(tree):
    if isinstance(node, ast.ImportFrom) and node.module == 'datetime':
        for name in node.names:
            if name.name == 'datetime':
                found_datetime = True
            if name.name == 'timedelta':
                found_timedelta = True

if not found_datetime:
    raise AssertionError('Step 1: Missing import: from datetime import datetime')
if not found_timedelta:
    raise AssertionError('Step 1: Missing import: from datetime import timedelta')

print('TEST_PASSED')
